// This file is generated by AI.

// config.txt 解析与改写的断言。
//
// 这里钉住的是与语言服务 (crates/webgal-language-core/src/resource/config.rs) 一致的
// 那几条规则: 首个 `:` 分隔键值, 行内首个 `;` 之后是注释, 同名配置取值时"后者胜"。
// 侧栏摘要读的就是这份结果, 规则一旦分叉, 界面显示的名字会和服务端诊断打架。

import { describe, expect, it } from 'vitest';

import {
  gameConfigSummary,
  gameConfigValue,
  setGameConfigValue,
  setGameConfigValues,
} from '../src/lib/gameConfig';

describe('gameConfigSummary', () => {
  it('汇总侧栏需要的字段', () => {
    const entries = [
      { name: 'Game_name', value: '星海叙事', comment: '' },
      { name: 'Game_key', value: 'key-1', comment: '' },
      { name: 'Description', value: '一个测试项目', comment: '' },
      { name: 'Title_img', value: 'cover.png', comment: '' },
      { name: 'Title_bgm', value: 'bgm.ogg', comment: '' },
      { name: 'Game_Logo', value: 'logo.png', comment: '' },
    ];
    expect(gameConfigSummary(entries)).toEqual({
      name: '星海叙事',
      gameKey: 'key-1',
      description: '一个测试项目',
      titleImg: 'cover.png',
      titleBgm: 'bgm.ogg',
      logo: 'logo.png',
    });
  });

  it('缺字段时给出空串而不是 undefined', () => {
    expect(gameConfigSummary([])).toEqual({
      name: '',
      gameKey: '',
      description: '',
      titleImg: '',
      titleBgm: '',
      logo: '',
    });
  });
});

describe('setGameConfigValue', () => {
  it('改写已有配置并保留行内注释', () => {
    const next = setGameConfigValue('Game_name:旧; 游戏名称\n', 'Game_name', '新');
    expect(next).toBe('Game_name:新; 游戏名称\n');
  });

  it('配置不存在时追加到末尾', () => {
    const next = setGameConfigValue('Game_name:旧;\n', 'Game_key', 'key-1');
    expect(next).toBe('Game_name:旧;\nGame_key:key-1;\n');
  });

  it('结尾没有换行的文件不会在追加后被粘住', () => {
    const next = setGameConfigValue('Game_name:旧;', 'Game_key', 'key-1');
    expect(next).toBe('Game_name:旧;\nGame_key:key-1;');
  });

  it('空文件直接生成一行', () => {
    expect(setGameConfigValue('', 'Game_name', '新')).toBe('Game_name:新;');
  });

  it('只改写最后一条同名配置', () => {
    const next = setGameConfigValue('Game_name:一;\nGame_name:二;\n', 'Game_name', '三');
    expect(next).toBe('Game_name:一;\nGame_name:三;\n');
  });

  it('空值行不算已有配置, 改写时追加有效配置', () => {
    const next = setGameConfigValue('Game_key:;\n', 'Game_key', 'key-1');
    expect(next).toBe('Game_key:;\nGame_key:key-1;\n');
  });

  it('一次改写多条 (新建项目写名称与识别码)', () => {
    const next = setGameConfigValues('Game_name:旧;\nDescription:简介;\n', {
      Game_name: '新',
      Game_key: 'key-1',
    });
    expect(next).toBe('Game_name:新;\nDescription:简介;\nGame_key:key-1;\n');
  });
});
